def countBoundedPairs(nums1, nums2, diff):
    d = [x - y for x, y in zip(nums1, nums2)]

    def solve(a):
        if len(a) <= 1:
            return a, 0
        mid = len(a) // 2
        left, cl = solve(a[:mid])
        right, cr = solve(a[mid:])
        total = cl + cr
        i = 0
        for r in right:
            while i < len(left) and left[i] <= r + diff:
                i += 1
            total += i
        return sorted(left + right), total

    return solve(d)[1]
